interface SignatureProps {
  className?: string;
  /** Write the signature out as it was drawn (~3.2s). */
  animate?: boolean;
}

export function Signature({ className, animate = true }: SignatureProps) {
  const [writing, setWriting] = useState(false);

  useEffect(() => {
    if (!animate || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    setWriting(true);
  }, [animate]);

  return (
    <svg viewBox="28 2 808 578" role="img" aria-label="Isaac's signature" className={cn('h-auto overflow-visible', className)}>
      <g fill="none" stroke="currentColor" strokeWidth={10.2} strokeLinecap="round" strokeLinejoin="round">
        {PIECES.map(([d, delay, duration]) => (
          <path
            key={d}
            d={d}
            pathLength={1}
            className={writing ? 'signature-stroke' : undefined}
            style={writing ? { animationDelay: `${delay + 0.3}s`, animationDuration: `${duration}s` } : undefined}
          />
        ))}
      </g>
    </svg>
  );
}
